package org.eclipse.rdf4j.sail.nativerdf;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.atomic.AtomicBoolean;

import org.junit.jupiter.api.Test;

class QueryBenchmarkStreamCleanupTest {
	@Test
	void successfulQueryReadClosesItsOwnedStream() throws Exception {
		AtomicBoolean closed = new AtomicBoolean();
		InputStream input = new ByteArrayInputStream("SELECT * { ?s ?p ?o }".getBytes(StandardCharsets.UTF_8)) {
			@Override
			public void close() throws IOException {
				closed.set(true);
				super.close();
			}
		};
		assertEquals("SELECT * { ?s ?p ?o }", QueryBenchmarkTest.readQuery(input));
		assertTrue(closed.get(), "query resource must be closed after loading");
	}

	@Test
	void failedQueryReadClosesItsOwnedStreamAndPreservesFailure() {
		AtomicBoolean closed = new AtomicBoolean();
		IOException failure = new IOException("query read failed");
		InputStream input = new InputStream() {
			@Override
			public int read() throws IOException {
				throw failure;
			}

			@Override
			public void close() {
				closed.set(true);
			}
		};
		assertSame(failure, assertThrows(IOException.class, () -> QueryBenchmarkTest.readQuery(input)));
		assertTrue(closed.get(), "query resource must be closed after a failed read");
	}

	@Test
	void failedCloseIsSuppressedOnTheOriginalReadFailure() {
		IOException readFailure = new IOException("read failed");
		IOException closeFailure = new IOException("close failed");
		InputStream input = new InputStream() {
			@Override
			public int read() throws IOException {
				throw readFailure;
			}

			@Override
			public void close() throws IOException {
				throw closeFailure;
			}
		};
		assertSame(readFailure, assertThrows(IOException.class, () -> QueryBenchmarkTest.readQuery(input)));
		assertEquals(1, readFailure.getSuppressed().length);
		assertSame(closeFailure, readFailure.getSuppressed()[0]);
	}
}
